import unittest

from strutil import slug


class T(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(slug("Hello World"), "hello-world")

    def test_trim(self):
        self.assertEqual(slug("  A b "), "a-b")


if __name__ == "__main__":
    unittest.main()

